const HUMANOID_ARMOR = /* @__PURE__ */ new Set([
	"armor_stand",
	"zombie",
	"husk",
	"drowned",
	"zombie_villager",
	"giant",
	"skeleton",
	"stray",
	"bogged",
	"parched",
	"wither_skeleton",
	"piglin",
	"piglin_brute",
	"zombified_piglin"
]);
const ARMED_MOBS = /* @__PURE__ */ new Set([
	...HUMANOID_ARMOR,
	"pillager",
	"allay",
	"vex"
]);
const HEAD_ITEMS = /* @__PURE__ */ new Set([
	...HUMANOID_ARMOR,
	"villager",
	"wandering_trader"
]);
const SADDLED_MOBS = /* @__PURE__ */ new Set([
	"pig",
	"strider",
	"horse",
	"donkey",
	"mule",
	"skeleton_horse",
	"zombie_horse",
	"camel",
	"camel_husk",
	"nautilus",
	"zombie_nautilus"
]);
const BODY_EQUIPMENT = {
	horse: "horse_body",
	skeleton_horse: "horse_body",
	zombie_horse: "horse_body",
	wolf: "wolf_body",
	llama: "llama_body",
	trader_llama: "llama_body",
	happy_ghast: "happy_ghast_body",
	nautilus: "nautilus_body",
	zombie_nautilus: "nautilus_body"
};
const itemName = (stack) => String(stack?.id || "").replace(/^minecraft:/, "");
function equipmentStack(value) {
	return value?.id && itemName(value) !== "air" && Number(value.count ?? value.Count ?? 1) > 0 ? value : null;
}
function readEquipment(nbt = {}) {
	const old = {
		head: nbt.ArmorItems?.[3],
		chest: nbt.ArmorItems?.[2],
		legs: nbt.ArmorItems?.[1],
		feet: nbt.ArmorItems?.[0],
		mainhand: nbt.HandItems?.[0],
		offhand: nbt.HandItems?.[1],
		body: nbt.body_armor_item || nbt.ArmorItem || nbt.DecorItem,
		saddle: nbt.SaddleItem || (nbt.Saddle ? {
			id: "minecraft:saddle",
			count: 1
		} : null)
	};
	return Object.fromEntries(Object.keys(old).map((slot) => [slot, equipmentStack(Object.hasOwn(nbt.equipment || {}, slot) ? nbt.equipment[slot] : old[slot])]));
}
function itemComponent(stack, key) {
	return stack?.components?.["minecraft:" + key] ?? stack?.components?.[key];
}
function equippable(stack) {
	return itemComponent(stack, "equippable") || EQUIPMENT_ITEMS[itemName(stack)]?.equippable;
}
function equipmentDye(stack) {
	const value = itemComponent(stack, "dyed_color") ?? stack?.tag?.display?.color;
	const color = typeof value === "object" ? value?.rgb : value;
	return Number.isFinite(color) ? color & 16777215 : null;
}
function hasGlint(stack) {
	const override = itemComponent(stack, "enchantment_glint_override");
	if (override !== void 0) return !!override;
	const enchants = itemComponent(stack, "enchantments");
	return !!(Object.keys(enchants?.levels || enchants || {}).length || stack?.tag?.Enchantments?.length || stack?.tag?.ench?.length);
}

